import os
from collections import Counter

# Read all valid words
words = []
with open('/workdir/data/dict.txt') as f:
    for line in f:
        word = line.strip()
        if word and word.isalpha():
            words.append(word.lower())

# Create a set for O(1) lookups
word_set = set(words)

# Try shift by 1 derangement: a->b, b->c, ..., z->a
def shift1(word):
    return ''.join(chr((ord(c) - ord('a') + 1) % 26 + ord('a')) for c in word)

# Find words where both word and shifted word are valid
valid_words = []
for word in words:
    if len(word) >= 4:
        shifted = shift1(word)
        if shifted in word_set:
            valid_words.append(word)

print(f'Words with shifted valid counterparts: {len(valid_words)}')
print(f'First 20: {valid_words[:20]}')
