import os
import re

# Read all valid words (strictly a-z only)
words = []
with open('/workdir/data/dict.txt') as f:
    for line in f:
        word = line.strip()
        if word and re.match(r'^[a-z]+$', word):
            words.append(word.lower())

word_set = set(words)

# Try different shifts
best_shift = None
best_words = []
best_unique = 0

for shift in range(1, 26):
    mapping = {}
    for i in range(26):
        mapping[chr(ord('a') + i)] = chr(ord('a') + (i + shift) % 26)

    valid_words = []
    for word in words:
        if len(word) >= 4:
            shifted = ''.join(mapping[c] for c in word)
            if shifted in word_set:
                valid_words.append(word)

    unique_chars = set()
    for word in valid_words:
        for c in word:
            unique_chars.add(c)

    print(f"Shift {shift}: {len(valid_words)} words, {len(unique_chars)} unique chars")

    if len(valid_words) > len(best_words) or (len(valid_words) == len(best_words) and len(unique_chars) > best_unique):
        best_shift = shift
        best_words = valid_words
        best_unique = len(unique_chars)

# Use the best shift
mapping = {}
for i in range(26):
    mapping[chr(ord('a') + i)] = chr(ord('a') + (i + best_shift) % 26)

print(f"\nBest shift: {best_shift}, {len(best_words)} words, {best_unique} unique chars")

# Pick 15 words
selected = best_words[:15]

# Count unique characters in selected words
unique_chars = set()
for word in selected:
    for c in word:
        unique_chars.add(c)

print(f"Selected words: {selected}")
print(f"Unique characters: {len(unique_chars)}")

# Write mapping file
with open('/workdir/solution/mapping.txt', 'w') as f:
    for i in range(26):
        f.write(mapping[chr(ord('a') + i)] + '\n')

# Write words file
with open('/workdir/solution/words.txt', 'w') as f:
    for word in selected:
        f.write(word + '\n')

print("Solution created successfully.")
